{
  "findings": [
    {
      "check_id": "CKV_AWS_144",
      "title": "S3 bucket does not have cross-region replication enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket is not configured for cross-region replication, which could lead to data loss in case of a region-specific disaster."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket does not have object lock enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have object lock enabled, which could lead to accidental or malicious deletion of objects."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket does not have versioning enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have versioning enabled, making it difficult to recover from accidental deletion or overwrite of objects."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"flowbucket\" {
  bucket        = \"${local.resource_prefix.value}-flowlogs\"
  force_destroy = true
  tags = merge({
    Name        = \"${local.resource_prefix.value}-flowlogs\"
    Environment = local.resource_prefix.value
    }, {
  })
  versioning {
    enabled = true
  }
}",
  "fix_summary": "Enabled versioning on the S3 bucket to allow for recovery from accidental deletion or overwrite of objects. Note that cross-region replication and object lock were not enabled as they require additional configuration and resources not present in the original file."
}
